import glob,re,subprocess as s,sys
names=set()
for f in glob.glob('_tools/*.py')+glob.glob('.claude/skills/*/*.py'):
    t=open(f).read()
    if f.endswith('kbfacts.py'):continue
    names|=set(re.findall(r'\bkbfacts\.([A-Za-z_]\w*)\b(?!\.py)',t))-{'py'}
    for m in re.findall(r'from kbfacts import (\([^)]*\)|[^\n]+)',t):m=m.strip('()');names|={x.strip().split(' as ')[0] for x in m.replace(chr(10),',').split(',') if x.strip() and not x.strip().startswith('#')}
code='import sys;sys.path.insert(0,"_tools");import kbfacts;miss=[x for x in sys.argv[1:] if not hasattr(kbfacts,x)];print("missing:",miss);sys.exit(1 if miss else 0)'
p=s.run([sys.executable,'-c',code,*sorted(names)],capture_output=True,text=True);print(len(names),'names',p.stdout,p.stderr[-300:]);sys.exit(p.returncode)
